(function(global){"use strict";const TOPIC="kx-6a-02";const rows=[{"passageTitle":"節約的舊書角","passage":"星期五，品妍和子翔來到班級圖書角，準備整理二手書活動。原本大家以為照著舊方法進行就夠了，沒想到出現新的問題：幾本封面磨損的書被誤當成廢紙。兩人沒有急著責怪誰，而是先整理已知的情況。仔細檢查之後，他們發現書頁完整，換掉破損書皮就能繼續閱讀。於是大家決定先修補再分類上架，並請另一組同學看看是否仍有疏漏。這次調整花了不少時間，但展示成果比原先更清楚。回程時，他們交換心得，認為珍惜資源不等於勉強留住不能使用的物品。下次遇到類似情況，他們也想先蒐集證據，再選擇做法。","qs":[["他們這次想完成什麼任務？","整理二手書活動",["參加游泳競賽","預約火車車票","準備球隊制服"]],["準備過程中遇到了什麼問題？","幾本封面磨損的書被誤當成廢紙",["忘了活動地點","器材突然被搬空","所有人都提早離開"]],["查證之後，他們發現什麼？","書頁完整，換掉破損書皮就能繼續閱讀",["紀錄完全沒有問題","任何推測都可以當事實","同學的想法沒有差別"]],["他們最後如何調整？","先修補再分類上架",["把工作交給別人便不再理會","不經確認就取消任務","拒絕參考新的意見"]],["這個經驗最能說明哪一個道理？","珍惜資源不等於勉強留住不能使用的物品",["速度永遠比理解重要","遇到批評應直接放棄","第一個判斷一定正確"]]]},{"passageTitle":"水表上的提醒","passage":"星期五，佳穎與柏翰來到社區活動中心，準備檢查用水紀錄。原本大家以為照著舊方法進行就夠了，沒想到出現新的問題：每月使用量突然增加，大家都猜是管線故障。兩人沒有急著責怪誰，而是先整理已知的情況。仔細檢查之後，他們發現飲水機旁的水龍頭沒有關緊才是原因。於是大家決定查閱紀錄並請管理員維修，並請另一組同學看看是否仍有疏漏。這次調整花了不少時間，但展示成果比原先更清楚。回程時，他們交換心得，認為先調查原因比責怪任何人更有效。下次遇到類似情況，他們也想先蒐集證據，再選擇做法。","qs":[["他們這次想完成什麼任務？","檢查用水紀錄",["參加游泳競賽","預約火車車票","準備球隊制服"]],["準備過程中遇到了什麼問題？","每月使用量突然增加，大家都猜是管線故障",["忘了活動地點","器材突然被搬空","所有人都提早離開"]],["查證之後，他們發現什麼？","飲水機旁的水龍頭沒有關緊才是原因",["紀錄完全沒有問題","任何推測都可以當事實","同學的想法沒有差別"]],["他們最後如何調整？","查閱紀錄並請管理員維修",["把工作交給別人便不再理會","不經確認就取消任務","拒絕參考新的意見"]],["這個經驗最能說明哪一個道理？","先調查原因比責怪任何人更有效",["速度永遠比理解重要","遇到批評應直接放棄","第一個判斷一定正確"]]]},{"passageTitle":"分享工具箱","passage":"星期五，思妤跟家豪來到學校木工教室，準備安排共用工具。原本大家以為照著舊方法進行就夠了，沒想到出現新的問題：有人想一次買進所有新工具。兩人沒有急著責怪誰，而是先整理已知的情況。仔細檢查之後，他們發現現有工具只有部分零件老舊，並非整套不能用。於是大家決定列出需求再採購必要的替換零件，並請另一組同學看看是否仍有疏漏。這次調整花了不少時間，但展示成果比原先更清楚。回程時，他們交換心得，認為節制支出也要考量安全和實際需要。下次遇到類似情況，他們也想先蒐集證據，再選擇做法。","qs":[["他們這次想完成什麼任務？","安排共用工具",["參加游泳競賽","預約火車車票","準備球隊制服"]],["準備過程中遇到了什麼問題？","有人想一次買進所有新工具",["忘了活動地點","器材突然被搬空","所有人都提早離開"]],["查證之後，他們發現什麼？","現有工具只有部分零件老舊，並非整套不能用",["紀錄完全沒有問題","任何推測都可以當事實","同學的想法沒有差別"]],["他們最後如何調整？","列出需求再採購必要的替換零件",["把工作交給別人便不再理會","不經確認就取消任務","拒絕參考新的意見"]],["這個經驗最能說明哪一個道理？","節制支出也要考量安全和實際需要",["速度永遠比理解重要","遇到批評應直接放棄","第一個判斷一定正確"]]]},{"passageTitle":"用餐後的盤點","passage":"星期五，若晴和承恩來到班級午餐區，準備改善餐後整理。原本大家以為照著舊方法進行就夠了，沒想到出現新的問題：每次餐後剩下許多未使用的餐具。兩人沒有急著責怪誰，而是先整理已知的情況。仔細檢查之後，他們發現多數同學習慣先取太多備品，後來才發現用不到。於是大家決定先依人數分配並記錄實際使用量，並請另一組同學看看是否仍有疏漏。這次調整花了不少時間，但展示成果比原先更清楚。回程時，他們交換心得，認為妥善規畫比事後提醒更能減少浪費。下次遇到類似情況，他們也想先蒐集證據，再選擇做法。","qs":[["他們這次想完成什麼任務？","改善餐後整理",["參加游泳競賽","預約火車車票","準備球隊制服"]],["準備過程中遇到了什麼問題？","每次餐後剩下許多未使用的餐具",["忘了活動地點","器材突然被搬空","所有人都提早離開"]],["查證之後，他們發現什麼？","多數同學習慣先取太多備品，後來才發現用不到",["紀錄完全沒有問題","任何推測都可以當事實","同學的想法沒有差別"]],["他們最後如何調整？","先依人數分配並記錄實際使用量",["把工作交給別人便不再理會","不經確認就取消任務","拒絕參考新的意見"]],["這個經驗最能說明哪一個道理？","妥善規畫比事後提醒更能減少浪費",["速度永遠比理解重要","遇到批評應直接放棄","第一個判斷一定正確"]]]}];const specs=[];rows.forEach((r,i)=>{const audit=r.qs.map(q=>({answer:q[1],source:"自編原創短文〈"+r.passageTitle+"〉",original:true}));specs.push({id:TOPIC+"-reading-L"+(i+1)+"-0"+(i+1),type:"reading",level:i+1,tag:["basic","trap","extend","basic"][i],poolKey:null,lessonBased:false,leakTerms:[],audit,gen:()=>({passageTitle:r.passageTitle,passage:r.passage,questions:r.qs.map((q,k)=>({stem:q[0],options:[q[1]].concat(q[2]),answer:0,explain:"依據原創短文〈"+r.passageTitle+"〉第"+(k+1)+"題所問，可由情節找到「"+q[1]+"」。"}))})});});global.ExamBank.register(TOPIC,"original-reading-draft",specs);})(typeof window!=="undefined"?window:globalThis);
